<?php elseif($tab==='gradebook'):?><section class="lms-panel"><h2>Course Gradebook</h2><p class="hint">Assignment grades + latest quiz percentages. Final-grade policy can be handled by the teaching team; no fabricated grade is calculated.</p><div class="course-table"><table><thead><tr><th>Student</th><th>Progress</th><th>Assignment Avg.</th><th>Quiz Avg.</th><th>Status</th></tr></thead><tbody><?php foreach($enrollments as $e):$sq=$pdo->prepare('SELECT * FROM lms_students_v1360 WHERE id=?');$sq->execute([$e['student_id']]);$st=$sq->fetch(PDO::FETCH_ASSOC)?:[];$gq=$pdo->prepare("SELECT AVG(s.score) FROM lms_assignment_submissions_v1360 s JOIN lms_assignments_v1360 a ON a.id=s.assignment_id WHERE s.tenant_id=? AND s.student_id=? AND a.course_id=? AND s.status='graded'");$gq->execute([$tid,$e['student_id'],$id]);$aavg=$gq->fetchColumn();$qq=$pdo->prepare("SELECT AVG(x.percent) FROM (SELECT qa.quiz_id,MAX(qa.id) id FROM lms_quiz_attempts_v1360 qa JOIN lms_quizzes_v1360 qz ON qz.id=qa.quiz_id WHERE qa.tenant_id=? AND qa.student_id=? AND qz.course_id=? GROUP BY qa.quiz_id) z JOIN lms_quiz_attempts_v1360 x ON x.id=z.id");$qq->execute([$tid,$e['student_id'],$id]);$qavg=$qq->fetchColumn();?><tr><td><b><?=sk1360_h(sk1360_user_label((int)($st['user_id']??0)))?></b><small><?=sk1360_h($st['student_no']??'')?></small></td><td><?=$e['progress_percent']?>%</td><td><?=$aavg===false||$aavg===null?'—':number_format((float)$aavg,1)?></td><td><?=$qavg===false||$qavg===null?'—':number_format((float)$qavg,1).'%'?></td><td><?=sk1360_h($e['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></div><?php page_end();
